'use strict';
(() => {
 const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const KEY='FoldPutt.PlayClub.v1',media=matchMedia('(prefers-reduced-motion: reduce)');
 let saved={},storageOK=true;try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};}catch{saved={};storageOK=false;}
 const defaults={shortlist:[],ratings:{},notes:{},visited:[],wins:{},mastery:{},food:[],stamps:[],quotes:[],garden:Array(9).fill(null),seeds:0,sleep:[],postcards:[],daily:{},ghost:{},relay:null,maps:[null,null,null],reduced:media.matches,sound:false,classic:false};
 let store={...defaults,...saved};for(const key of ['shortlist','visited','food','stamps','quotes','garden','sleep','postcards','maps'])if(!Array.isArray(store[key]))store[key]=defaults[key];for(const key of ['ratings','notes','wins','mastery','daily','ghost'])if(!store[key]||typeof store[key]!=='object'||Array.isArray(store[key]))store[key]={};
 let view='home',current=null,filter='all',game=null,epoch=0,jobs=new Set(),option=0,level=0,round={scores:[],duel:[[],[]],player:0,names:['小草','小风']},lastResult=null,activeCollection=false;
 let draft=FP.copy(FP.maps[0]),history=[],future=[],tool='wall',editing=false,editorDirty=false,verifiedDraft=false,ambient=null;
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(store));}catch{storageOK=false;toast('本地存储不可用，当前体验仍可继续；请导出候选清单。');}};
 const reduced=()=>media.matches||store.reduced;
 const schedule=(fn,ms)=>{const token=epoch,id=setTimeout(()=>{jobs.delete(id);if(token===epoch)fn();},ms);jobs.add(id);};
 function teardown(){epoch++;jobs.forEach(clearTimeout);jobs.clear();game?.destroy();game=null;}
 function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),3200);}
 const btn=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
 const icon=FP.icon;
 const dateAt=n=>{const d=new Date();d.setDate(d.getDate()-n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 const streak=scores=>scores.reduce((r,n)=>{r.now=n===1?r.now+1:0;r.best=Math.max(r.best,r.now);return r;},{now:0,best:0});
 const winKey=()=>`${current.id}-${option}-${level}`;
 const selected=id=>store.shortlist.includes(id);
 function chrome(content){
  document.body.classList.toggle('reduced',reduced());
  $('app').innerHTML=`<div class="shell"><aside class="sidebar"><div><div class="brand"><i class="brand-mark"></i>FoldPutt.</div><div class="eyebrow" style="margin-top:8px">THE LITTLE PLAY CLUB</div></div><nav aria-label="主要导航">${btn(icon('grid')+'<span>玩法体验馆</span>','home','nav '+(view==='home'?'active':''))}${btn(icon('star')+`<span>我的候选</span><span>${store.shortlist.length}</span>`,'compare','nav '+(view==='compare'?'active':''))}${btn(icon('book')+'<span>体验收藏</span>','shelf','nav '+(view==='shelf'?'active':''))}</nav><div class="side-note"><strong>先玩一局，再做选择。</strong>12 个方向 · 本地可玩原型<br>收藏喜欢的玩法，写下理由，导出下一版清单。<div class="line"></div>免费体验 · 无广告 · 无等待</div></aside><div class="body"><header class="topbar"><span class="eyebrow">好玩研究所 / ${view==='play'?esc(current.en):'VOL. 01 · 十二种小快乐'}</span><div class="top-tools">${btn(icon('moon'),'settings','round','aria-label="体验设置"')}${btn('怎么选？','guide','quiet')}</div></header>${!storageOK?'<div class="storage-warning">此环境无法保存本地进度；可以继续体验并导出选择。</div>':''}<main id="main" class="main" tabindex="-1">${content}<footer class="footer"><span>FoldPutt 玩法概念体验 · 可直接击球 / 交互 / 收藏</span><span>本地原型 · 市场价值为待验证假设</span></footer></main></div></div>`;
 }
 function home(){window.scrollTo(0,0);view='home';teardown();activeCollection=false;const list=FP.features.filter(f=>filter==='all'||f.kind===filter);
  chrome(`<section class="hero"><div class="hero-copy"><span class="eyebrow">A LITTLE PUTT. A LOT OF JOY.</span><h1>把一颗小球，<br>玩出十二种快乐。</h1><p>不止看看。挑一张草坪，真正打一局。<br>收集、比赛、种花，甚至造一张自己的地图。</p><div class="row">${btn('先玩反弹解谜 '+icon('arrow'),'open:puzzle','primary')}${btn('看看我的候选','compare','quiet')}</div></div><div class="hero-art">${FP.art(FP.features[3],true)}<span class="hero-label">每一个点子，都能亲手试一试。</span></div></section><section><div class="section-head"><div><div class="eyebrow">THE PLAYGROUND</div><h2>哪一种，会让你想再玩一局？</h2></div><div class="filters" aria-label="玩法分类">${[['all','全部 12'],['delight','沙雕快乐'],['cozy','慢慢治愈'],['skill','技巧挑战'],['social','一起创造']].map(([id,title])=>btn(title,'filter:'+id,'filter '+(filter===id?'active':''),`aria-pressed="${filter===id}"`)).join('')}</div></div><div class="cards">${list.map(f=>`<article class="feature-card"><div class="art-wrap">${FP.art(f)}<span class="card-number">${f.n}</span><span class="card-tag">${f.tag} · ${f.recommend}</span></div><div class="card-body"><h3>${f.title}</h3><p>${f.desc}</p><div class="card-foot">${btn('进去玩 '+icon('arrow'),'open:'+f.id,'quiet')}${btn(icon(selected(f.id)?'check':'star'),'pick:'+f.id,'bookmark',`aria-label="${selected(f.id)?'移除候选':'加入候选'}：${f.title}" aria-pressed="${selected(f.id)}"`)}</div></div></article>`).join('')}</div></section>`);
 }
 function goHome(){closeModal();location.hash='home';if(view==='home')home();}
 function openFeature(id,reset=true){const f=FP.features.find(f=>f.id===id);if(!f)return;closeModal();teardown();view='play';current=f;activeCollection=false;if(reset){option=0;level=f.id==='sleep'?Math.max(0,Array.from({length:9},(_,i)=>i).find(i=>!store.sleep[i])??0):0;round={scores:[],duel:[[],[]],player:0,names:round.names||['小草','小风']};lastResult=null;}if(!store.visited.includes(id)){store.visited.push(id);save();}if(f.id==='editor'){editing=true;draft={...FP.copy(FP.maps[0]),name:'我的小草坪',walls:[],sand:[],water:[],stars:[],theme:'editor'};history=[];future=[];verifiedDraft=false;editorDirty=false;}
  historyReplace('play/'+id);renderPlay();window.scrollTo(0,0);
 }
 function historyReplace(hash){if(location.hash!=='#'+hash)window.history.replaceState(null,'','#'+hash);}
 function gameMap(){if(current.id==='editor')return {...FP.copy(draft),theme:'editor',id:'my-map'};return FP.mapFor(current,option,level,current.id==='daily'?dateAt(option):'');}
 function titleBar(){return `<div class="content-title"><div><div class="row"><button class="quiet btn" data-action="home" style="padding:0 5px 0 0">${icon('back')}<span>全部玩法</span></button><span class="pill">${current.tag} / ${current.n}</span></div><h1>${current.title}</h1><p class="muted">${current.pitch}</p></div>${btn(icon(selected(current.id)?'check':'star')+(selected(current.id)?'已加入候选':'加入候选'),'pick:'+current.id,'bookmark',`aria-pressed="${selected(current.id)}"`)}</div>`;}
 function optionsPanel(){let f=current;
  const descriptions={food:'外观与表情变化，不改变击球数值。',office:'换一间办公室，也换一个下班故事。',mouth:'只在真实事件触发，不会一直打扰你。',garden:`现有种子 ${store.seeds} 颗 · 花园 ${store.garden.filter(x=>x!=null).length}/9`,sleep:`已点亮 ${store.sleep.filter(Boolean).length}/9 颗星 · 可随时暂停`,travel:'每个目的地有三站可收集。',puzzle:'先打通，再追额外反弹徽章。',daily:'仅记录此浏览器的个人最好成绩。',duel:`当前：${round.names[round.player]} · 第 ${level+1}/3 洞`,ghost:store.ghost[gameMap().id]?'已有你自己的幽灵，可以再次挑战。':'还没有幽灵。完成这一局，留下第一条真实轨迹。',relay:`已完成 ${round.scores.length}/3 洞 · 合计 ${round.scores.reduce((a,b)=>a+b,0)} 杆`,editor:'先选工具，再点球场网格摆放。'};
  if(f.id==='editor')return editorPanel();
  return `<section class="panel"><h3>${f.id==='duel'?'赛程设置':f.id==='daily'?'选择挑战日':'这次想怎么玩？'}</h3><div class="option-list">${f.options.map((o,i)=>btn(o,'option:'+i,'',`aria-pressed="${option===i}"`)).join('')}</div><p style="margin-top:12px">${descriptions[f.id]}</p>${f.id==='duel'?`<div class="row" style="margin-top:10px">${btn('双方昵称','names','quiet')}</div>`:''}${f.levels>1&&!['duel','relay','sleep'].includes(f.id)?`<div class="line"></div><h3>${f.id==='puzzle'?'选择课题':'选择小地图'}</h3><div class="level-grid">${Array.from({length:f.levels},(_,i)=>btn(`${i+1}${f.id==='puzzle'&&store.mastery[`puzzle-${i}`]?' ★':store.wins[`${f.id}-${option}-${i}`]?' ✓':''}`,'level:'+i,level===i?'selected':'',`aria-label="地图 ${i+1}"`)).join('')}</div>`:''}<div class="goal">${f.goal}</div></section><section class="panel"><h3>${f.extra}</h3>${smallCollection()}${btn('打开'+f.extra+' '+icon('arrow'),'collection','quiet')}</section><section class="panel"><h3>这个玩法，值得做吗？</h3><p>${f.hook}</p><div class="row" style="margin-top:14px"><span class="pill">工作量 ${f.cost}</span>${btn('查看取舍','insight','quiet')}</div></section>`;
 }
 function smallCollection(){const f=current;switch(f.id){case'garden':return `<div class="badge-progress"><span style="width:${store.garden.filter(x=>x!=null).length/9*100}%"></span></div><p>${store.seeds} 颗待种的种子。点击空格种下，已种花可移栽。</p>`;case'sleep':return `<p>${Array.from({length:9},(_,i)=>store.sleep[i]?'★':'☆').join(' ')}<br>没有连续签到要求。</p>`;case'duel':return `<div class="tiny-record"><span>${esc(round.names[0])}</span><b>${round.duel[0].reduce((a,b)=>a+b,0)} 杆</b></div><div class="tiny-record"><span>${esc(round.names[1])}</span><b>${round.duel[1].reduce((a,b)=>a+b,0)} 杆</b></div>`;case'ghost':{const best=store.ghost[gameMap().id];return `<p>${best?`个人最佳 ${best.strokes} 杆 · 轨迹 ${best.trace.length} 点`:'先打一局，幽灵来自你自己。'}</p>`;}case'mouth':return `<p>已收录 ${store.quotes.length}/6 种真实事件台词。</p>`;case'travel':return `<p>已收集 ${store.postcards.length} 张旅行明信片。</p>`;case'food':return `<p>已收集 ${store.food.length}/9 枚点心印章。</p>`;case'office':return `<p>已获得 ${store.stamps.length} 种下班印章。</p>`;case'daily':return `<p>${store.daily[dateAt(option)]?`本日最佳 ${store.daily[dateAt(option)]} 杆`:'这一天还没有你的成绩。'}</p>`;case'relay':return `<p>个人整轮最佳：${store.relay??'尚未完成'}${store.relay?' 杆':''}。</p>`;default:return `<p>已打通 ${Object.keys(store.wins).filter(k=>k.startsWith(f.id+'-')).length} 个挑战。</p>`;}}
 function renderPlay(){teardown();view='play';activeCollection=false;const f=current,m=gameMap();chrome(`${titleBar()}<div class="workspace"><section class="game-main">${f.id==='duel'?`<div class="step-note">友谊赛 · 第 ${level+1}/3 洞 · <strong>${esc(round.names[round.player])} 的回合</strong>。同一洞先 A 后 B，结算后传手机。</div>`:f.id==='relay'?`<div class="step-note">三洞接力 · 第 ${level+1}/3 洞 · ${option===1?'挑战连续一杆；失手结束连击，仍可继续。':'比总杆，不限时、不淘汰。'}</div>`:f.id==='sleep'?`<div class="step-note">今晚第 ${level+1}/9 颗星 · 累了就停，下次可以接着来。</div>`:''}<div class="board-card"><header class="game-top"><div><strong>${esc(m.name)}</strong><small>${f.id==='editor'&&editing?'编辑模式 · 点网格放置':'球道 '+String(level+1).padStart(2,'0')+' / '+f.levels+' · '+(store.classic?'普通球':'表情球')}</small></div><div class="row"><span class="pill">PAR ${m.par}</span><div class="score-block"><b id="stroke-count">0</b> 杆</div></div></header><div class="canvas-wrap"><canvas id="game-canvas" width="760" height="500"></canvas><div class="board-message" id="board-message">${editing&&f.id==='editor'?'点右侧工具，再点网格放置':'按住小球或下方拉杆，向后拖，再松手。'}</div></div>${f.id==='editor'&&editing?`<div class="editor-status" id="editor-status">${mapStatus()}</div>`:`<div class="pull-footer"><div id="pullpad" class="pullpad" aria-label="拖拽拉杆" aria-disabled="false"><span></span></div><div class="pull-info"><strong id="phase-label" role="status" aria-live="polite">小球已停稳 · 可以击球</strong><p id="shot-detail">向反方向拖动，同时决定方向和力度</p><div class="power-track"><div id="power-fill" class="power-fill"></div></div></div><button class="btn primary hidden" id="show-result" data-action="result">查看结算</button>${btn(icon('pause'),'pause','round','aria-label="暂停"')}${btn(icon('reset'),'restart','round','aria-label="重开当局"')}</div>`}</div><div class="flow">${f.loop.map((x,i)=>`<span>${i+1} / ${x}</span>`).join('')}</div><details class="hint-panel"><summary>操作说明与键盘等价操作</summary>主操作：按住球或圆形拉杆，向反方向拖动，松手发射。滚动时不能再次击球。键盘：Tab 聚焦球场，按住方向键向后拉，松开方向键发射；Esc 取消。本原型有固定步长碰撞与摩擦，水池会送你回本杆起点，不扣生命。${f.id==='editor'?' 编辑器也可通过键盘：Tab 聚焦球场后使用下方“精确放置”。':''}</details><div class="feature-story"><div><h3>为什么想再来一局</h3><p>${f.return}</p></div><div><h3>打完之后试试</h3><p>${f.id==='editor'?'返回编辑，调整墙的位置；保存三份自己的地图。':'打开右侧“'+f.extra+'”，看看这局留下了什么。'}</p></div></div></section><aside class="side-panel">${optionsPanel()}</aside></div>`);
  game=new FP.Game($('game-canvas'),m,{skin:option,classic:store.classic,reduced:reduced(),ghost:f.id==='ghost'?store.ghost[m.id]:null,editor:f.id==='editor'&&editing,edit:editAt,event:onEvent,aim:aimUI});if($('pullpad'))game.bindPad($('pullpad'));if(f.id==='editor')updateEditor();
 }
 function aimUI(power){if($('power-fill'))$('power-fill').style.width=power*100+'%';if($('phase-label')&&game?.world.phase==='ready')$('phase-label').textContent=power>0?`松手击球 · 力度 ${Math.round(power*100)}%`:'小球已停稳 · 可以击球';}
 const phrases={shot:['走你！职业选手气质已上线。','小小地出发。'],collision:['我在测量墙壁。','叩，有点弹。'],near:['路过，给洞一点心理准备。','刚刚在叫我吗？'],water:['这是我的水下训练计划。','捡回来啦，再试一次。'],stop:['停这里，主要是看看风景。','歇一歇，再靠近一点。'],win:['计划之内！刚才都是铺垫。','到家啦，今天也很棒。']};
 function onEvent(type,w){if($('stroke-count'))$('stroke-count').textContent=w.strokes;const rolling=w.phase==='rolling';$('pullpad')?.setAttribute('aria-disabled',rolling||w.phase==='won'?'true':'false');$('pullpad')?.classList.toggle('locked',rolling||w.phase==='won');$('game-canvas')?.setAttribute('aria-disabled',rolling||w.phase==='won'?'true':'false');if($('phase-label'))$('phase-label').textContent=rolling?'小球滚动中 · 拉杆已锁定':w.phase==='won'?'入洞了！':'小球已停稳 · 可以击球';if($('shot-detail'))$('shot-detail').textContent=`碰墙 ${w.collisions} 次${w.map.stars.length?' · 点心 '+w.collected.size+'/'+w.map.stars.length:''}${w.rescues?' · 捡回 '+w.rescues+' 次':''}`;
  let message=type==='shot'?'好球路，从轻轻一拉开始。':type==='collision'?'借墙反弹，继续滚。':type==='pickup'?'收好一颗小点心。':type==='near'?'擦过洞口了，再靠近一点。':type==='water'?'捡回来啦，回到本杆起点。':type==='stop'?'停稳了。下一杆，由你决定。':'漂亮入洞！';
  if(current.id==='mouth'&&phrases[type]){if(!store.quotes.includes(type)){store.quotes.push(type);save();}message=option===2?'专注球路，保持安静。':phrases[type][option===1?1:0];}
  if(current.id==='office'){if(type==='shot')message='正在绕开临时会议…';if(type==='pickup')message='门禁卡到手，下班路线畅通。';if(type==='collision')message='被叫住了？换条路，继续走。';}
  if(current.id==='sleep'&&type==='stop')message='不用着急。下一杆，慢慢来。';if($('board-message'))$('board-message').textContent=message;
  if(['shot','pickup','win'].includes(type))tone(type);if(type==='win')win(w);
 }
 function win(w){$('show-result')?.classList.remove('hidden');lastResult={strokes:w.strokes,collisions:w.collisions,rescues:w.rescues,pickups:w.collected.size,trace:FP.copy(w.trace),map:FP.copy(w.map),option,level,time:w.time};const f=current,key=winKey();store.wins[key]=Math.min(store.wins[key]??Infinity,w.strokes);
  if(f.id==='food'&&w.collected.size===w.map.stars.length){const id=`${option}-${level}`;lastResult.newStamp=!store.food.includes(id);if(lastResult.newStamp)store.food.push(id);}
  if(f.id==='office'){const label=w.strokes<=w.map.par?'准点下班':w.rescues?'摸鱼归来':'曲线下班';if(!store.stamps.includes(label))store.stamps.push(label);lastResult.stamp=label;}
  if(f.id==='garden')store.seeds++;
  if(f.id==='puzzle'&&w.collisions>0&&w.strokes<=w.map.par)store.mastery[`puzzle-${level}`]=true;
  if(f.id==='sleep')store.sleep[level]=true;
  if(f.id==='daily')store.daily[dateAt(option)]=Math.min(store.daily[dateAt(option)]??Infinity,w.strokes);
  if(f.id==='ghost'){const old=store.ghost[w.map.id];lastResult.newBest=!old||w.strokes<old.strokes||(w.strokes===old.strokes&&w.time<old.time);if(lastResult.newBest)store.ghost[w.map.id]={strokes:w.strokes,time:w.time,trace:FP.copy(w.trace),name:w.map.name};}
  if(f.id==='relay')round.scores.push(w.strokes);
  if(f.id==='duel')round.duel[round.player].push(w.strokes);
  if(f.id==='editor')verifiedDraft=true;
  if(f.id==='travel'){const cardKey=`${option}-${level}`;const card={id:cardKey,place:f.options[option],station:level+1,strokes:w.strokes,trace:FP.copy(w.trace),map:FP.copy(w.map),note:'去远一点的地方，也照顾好自己。'};const i=store.postcards.findIndex(x=>x.id===cardKey);if(i>=0)store.postcards[i]=card;else store.postcards.push(card);lastResult.card=card;}
  if(f.id==='relay'&&level===2){const total=round.scores.reduce((a,b)=>a+b,0);store.relay=Math.min(store.relay??Infinity,total);}
  save();refreshPanel();schedule(resultModal,reduced()?180:850);
 }
 function resultModal(){const f=current,r=lastResult;if(!r)return;let title='WIN! 小小成就，收好。',body='',next='下一张地图';
  if(f.id==='food'){title='小点心，成功送达。';body=`<div class="result-stamp">${r.pickups===r.map.stars.length?(r.newStamp?'点心印章 +1':'这枚点心印章，已经收好啦'):'今天只顾着赶路，点心留给下一局。'}</div>`;}
  if(f.id==='office'){title='叮，打卡成功。';body=`<div style="text-align:center"><span class="stamp">${r.stamp}</span></div><p>门禁卡 ${r.pickups}/${r.map.stars.length} · ${r.strokes<=r.map.par?'今天，准时把自己交还给生活。':'多绕的路，就当下班前的散步。'}</p>`;}
  if(f.id==='mouth'){title=option===1?'绕点远路，也到家了。':'计划之内！';body='<p>嘴硬归嘴硬，进步是真的。新的台词已经放进你的语录册。</p>';}
  if(f.id==='garden'){title='这一杆，长成一颗种子。';body=`<div class="result-stamp">种子 +1 · 现在有 ${store.seeds} 颗</div>`;next='去花园种下';}
  if(f.id==='sleep'){title=level===8?'晚安，九颗星都亮了。':'今晚又亮了一颗星。';body=`<p>${store.sleep.filter(Boolean).length}/9 颗星。你可以继续，也可以在这里说晚安。</p>`;next=level===8?'看我的星空':'下一颗星';}
  if(f.id==='travel'){title='收到一张自己的明信片。';body=postcardMarkup(r.card);next='写寄语 / 保存卡片';}
  if(f.id==='puzzle'){title=r.collisions>0&&r.strokes<=r.map.par?'反弹徽章，拿到了！':'路线已打通。';body=`<p>${r.collisions>0&&r.strokes<=r.map.par?'你用墙壁完成了自己的解法。':'额外精通目标：至少一次反弹，并在标准杆内进洞。可以回去再试。'}</p>`;}
  if(f.id==='daily'){title='今天的球路，记下了。';body=`<p>${dateAt(option)} · 本地个人最佳 ${store.daily[dateAt(option)]} 杆。没有虚构的全球排行。</p>`;next='挑战昨天';}
  if(f.id==='ghost'){title=r.newBest?'这是新的自己。':'离自己的最好成绩更近一点。';body=`<p>本局 ${r.strokes} 杆 · 个人最佳 ${store.ghost[r.map.id].strokes} 杆。下一局会显示你真正打出的最佳轨迹。</p>`;next='再战自己的幽灵';}
  if(f.id==='duel'){const end=level===2&&round.player===1;title=end?'友谊赛，打完啦。':`${esc(round.names[round.player])} 完成本洞。`;body=scoreboard();if(end){const a=round.duel[0].reduce((a,b)=>a+b,0),b=round.duel[1].reduce((a,b)=>a+b,0);body+=`<div class="result-stamp">${a===b?'平局！友谊比胜负多一杆。':esc(round.names[a<b?0:1])+' 赢得本轮！'}</div>`;}next=end?'再来一轮':round.player===0?'交给 '+esc(round.names[1]):'进入下一洞';}
  if(f.id==='relay'){title=level===2?'三洞到站，漂亮收工。':'接力继续，手感正好。';const total=round.scores.reduce((a,b)=>a+b,0);body=`<p>本轮 ${round.scores.map((x,i)=>`第 ${i+1} 洞 ${x} 杆`).join(' / ')}<br>合计 ${total} 杆 · 一杆进洞 ${round.scores.filter(x=>x===1).length} 次 · 最长连续 ${streak(round.scores).best} 洞${level===2?' · 整轮个人最佳 '+store.relay+' 杆':''}</p>`;next=level===2?'再跑一轮':'继续下一洞';}
  if(f.id==='editor'){title='这张地图，亲测可通关。';body='<p>保存后会带上“本人已通关”标记。继续修改会重新变为待试玩。</p>';next='回编辑器保存';}
  showModal(title,`<div class="eyebrow">A GOOD LITTLE MOMENT</div><div class="result-score"><div><b>${r.strokes}</b><span>本局杆数</span></div><div><b>${r.collisions}</b><span>碰墙次数</span></div><div><b>${r.strokes<=r.map.par?'★ ★ ★':'★ ★'}</b><span>${r.strokes<=r.map.par?'标准杆内完成':'坚持打完也很棒'}</span></div></div>${body}<div class="dialog-actions">${btn('重玩本洞','retry-result','')}${btn(next,'next-result','primary')}</div><div class="dialog-actions">${btn(icon('star')+(selected(f.id)?'已在候选里':'喜欢，加入候选'),'pick:'+f.id,'quiet')}</div>`,{result:true});
 }
 function nextResult(){closeModal();const id=current.id;if(id==='garden'){collection();return;}if(id==='travel'){cardEditor(lastResult.card);return;}if(id==='sleep'&&level===8){collection();return;}if(id==='editor'){editing=true;renderPlay();return;}if(id==='daily'){option=(option+1)%3;renderPlay();return;}if(id==='ghost'){renderPlay();return;}if(id==='duel'){if(round.player===0){round.player=1;passDevice();return;}round.player=0;level++;if(level>=3){level=0;round.duel=[[],[]];}passDevice();return;}if(id==='relay'){level++;if(level>=3){level=0;round.scores=[];}renderPlay();return;}level=(level+1)%current.levels;renderPlay();}
 function passDevice(){renderPlay();game.pause(true);showModal('请把手机交给 '+esc(round.names[round.player]),`<p>第 ${level+1}/3 洞，双方使用完全相同的球场。准备好再开始。</p><div class="dialog-actions">${btn('我准备好了','resume','primary')}</div>`);}
 function retryResult(){if(current.id==='duel')round.duel[round.player].pop();if(current.id==='relay')round.scores.pop();closeModal();renderPlay();}
 function scoreboard(){return `<div class="stack">${round.names.map((name,i)=>`<div class="tiny-record"><strong>${esc(name)}</strong><span>${round.duel[i].map((n,j)=>`洞${j+1}：${n}`).join(' / ')||'还没开始'} · 总计 ${round.duel[i].reduce((a,b)=>a+b,0)} 杆</span></div>`).join('')}</div>`;}
 function showModal(title,content,opts={}){const modal=$('modal');if(modal.open)modal.close();game?.pause(true);modal.innerHTML=`<button class="round quiet dialog-close" data-action="close-modal" aria-label="关闭">${icon('close')}</button><h2 id="modal-title">${title}</h2>${content}`;modal.dataset.result=opts.result?'true':'false';modal.showModal();}
 function closeModal(){if($('modal').open)$('modal').close();game?.pause(false);}
 $('modal').addEventListener('cancel',()=>game?.pause(false));
 function insight(){showModal('这个点子，为什么值得试？',`<span class="pill">${current.recommend} · 预计工作量 ${current.cost}</span><div class="line"></div><h3>谁可能喜欢</h3><p>${current.audience}</p><div class="line"></div><h3>第一眼吸引力</h3><p>${current.hook}</p><h3 style="margin-top:15px">持续玩的理由</h3><p>${current.return}</p><div class="line"></div><h3>需要验证的风险</h3><p>${current.risk}</p><h3 style="margin-top:15px">小规模试玩观察</h3><p>${current.measure}</p><div class="dialog-actions">${btn('加入候选','pick:'+current.id,'primary')}${btn('继续体验','close-modal','')}</div>`);}
 function settings(){showModal('按你的节奏来',`<div class="setting-row"><div><strong>减少动态效果</strong><p>系统设置开启时强制生效；保留击球功能。</p></div>${btn(media.matches?'系统已开启':store.reduced?'已开启':'已关闭','motion','',`aria-pressed="${reduced()}" ${media.matches?'disabled':''}`)}</div><div class="setting-row"><div><strong>轻柔声音</strong><p>击球音与持续的轻环境底音；默认关闭。</p></div>${btn(store.sound?'已开启':'已关闭','sound','',`aria-pressed="${store.sound}"`)}</div><div class="setting-row"><div><strong>球的表现</strong><p>只改球外观，同一套关卡与击球规则。</p></div>${btn(store.classic?'普通球':'表情球','classic','')}</div><p>进度保存在此浏览器。没有账号、联网排行榜或付费入口。原型设置不改变 iOS 工程。</p><div class="dialog-actions">${btn('回到草坪','close-modal','primary')}</div>`);}
 function togglePick(id){if(selected(id))store.shortlist=store.shortlist.filter(x=>x!==id);else store.shortlist.push(id);save();const f=FP.features.find(x=>x.id===id);toast(`${selected(id)?'已加入候选':'已移出候选'}：${f.title}`);document.querySelectorAll(`[data-action="pick:${id}"]`).forEach(b=>{b.setAttribute('aria-pressed',selected(id));if(b.classList.contains('round')||b.closest('.card-foot'))b.innerHTML=icon(selected(id)?'check':'star');else b.innerHTML=icon(selected(id)?'check':'star')+(selected(id)?'已加入候选':'加入候选');});const nav=document.querySelector('[data-action="compare"] span:last-child');if(nav)nav.textContent=store.shortlist.length;if(view==='compare')compare();}
 function guide(){showModal('不要只挑最好看的，挑最想再玩的。',`<div class="stack"><p><b>1 / 先试三个不同方向</b><br>反弹解谜看手感；花园看成长；编辑器看内容潜力。</p><p><b>2 / 每个方向至少打完一局</b><br>继续打开收藏、赛程或再挑战，判断第二局的吸引力。</p><p><b>3 / 收藏 2–4 个，写下理由</b><br>候选页可以评分、备注、对比与导出。你选定后再进入正式 App 实现。</p><div class="note-callout">建议组合：一个传播钩子＋一个深度玩法＋一个持续目标。市场效果需要真实试玩数据验证。</div></div><div class="dialog-actions">${btn('开始体验','close-modal','primary')}</div>`);}
 function compare(){teardown();closeModal();view='compare';historyReplace('compare');const list=FP.features.filter(f=>selected(f.id));chrome(`<div class="content-title"><div><div class="eyebrow">YOUR NEXT CHAPTER</div><h1>把喜欢的，放进下一版。</h1><p class="muted">先选 2–4 个互补的方向。评分和理由只来自你的体验。</p></div>${btn(icon('save')+'导出候选清单','export-selection','primary')}</div><div class="note-callout"><strong>推荐思路：</strong>沙雕吸引第一眼，解谜提供深度，花园或旅程形成长期目标。下方是设计判断，不是市场验证结论。</div>${list.length?`<div class="compare-grid">${list.map(f=>`<article class="compare-card"><span class="eyebrow">${f.n} / ${f.en}</span><h3>${f.title}</h3><span class="pill">${f.recommend} · 工作量 ${f.cost}</span><p><b>吸引：</b>${f.hook}</p><p><b>复玩：</b>${f.return}</p><p><b>风险：</b>${f.risk}</p><label>你有多想再玩一局？</label><div class="ratings">${Array.from({length:5},(_,i)=>btn(icon('star'),'rate:'+f.id+':'+(i+1),i<(store.ratings[f.id]||0)?'on':'',`aria-label="${f.title}评分 ${i+1} 星" aria-pressed="${i<(store.ratings[f.id]||0)}"`)).join('')}</div><label for="note-${f.id}">添加理由 / 想改哪里</label><textarea id="note-${f.id}" data-note="${f.id}" maxlength="600" placeholder="例如：反弹很有成就感，想要更多巧妙地图。">${esc(store.notes[f.id]||'')}</textarea><div class="row" style="margin-top:15px">${btn('再玩一局','open:'+f.id,'primary')}${btn('移出候选','pick:'+f.id,'quiet')}</div></article>`).join('')}</div>`:`<div class="empty"><h2>还没有候选，先去玩一局。</h2><p>每个玩法右上角都可以加入候选。</p>${btn('回体验馆','home','primary')}</div>`}`);}
 function shelf(){teardown();closeModal();view='shelf';historyReplace('shelf');chrome(`<div class="content-title"><div><div class="eyebrow">SMALL THINGS YOU KEEP</div><h1>玩过的，都会留下点什么。</h1><p class="muted">已经体验 ${store.visited.length}/12 个方向；收藏来自你真实完成的操作。</p></div></div><div class="collection">${[['garden','我的花园',store.garden.filter(x=>x!=null).length+' 朵花 / '+store.seeds+' 颗种子'],['travel','旅行相册',store.postcards.length+' 张明信片'],['mouth','嘴硬语录',store.quotes.length+' 种事件台词'],['food','点心图鉴',store.food.length+' 枚印章'],['sleep','今晚星空',store.sleep.filter(Boolean).length+' 颗星'],['editor','我的地图',store.maps.filter(Boolean).length+' 个存档'],['office','下班印章',store.stamps.length+' 种结局'],['daily','每日成绩',Object.keys(store.daily).length+' 天的个人记录'],['ghost','个人幽灵',Object.keys(store.ghost).length+' 条最佳轨迹']].map(([id,title,count])=>`<article><span class="eyebrow">${FP.features.find(x=>x.id===id).en}</span><h3>${title}</h3><p class="muted" style="margin:12px 0">${count}</p>${btn('打开 '+icon('arrow'),'shelf-open:'+id,'quiet')}</article>`).join('')}</div>`);}
 function flowerSVG(type){const colors=['#fff8df','#df9c8c','#a7b9d5'],petals=Array.from({length:type===1?3:5},(_,i)=>`<ellipse cx="35" cy="26" rx="${type===1?9:7}" ry="14" transform="rotate(${i*(type===1?30:72)} 35 36)" fill="${colors[type]}" stroke="#749057" stroke-width="1"/>`).join('');return `<svg class="flower" aria-hidden="true" viewBox="0 0 70 90"><path d="M35 35v44m0-13q-27-13-17-22 17 4 17 22m0 3q23-17 18-27-16 7-18 27" stroke="#6b8652" stroke-width="3" fill="#94b875"/>${petals}<circle cx="35" cy="37" r="6" fill="#dcb75e"/></svg>`;}
 function refreshPanel(){const panel=document.querySelector('.side-panel');if(panel&&view==='play')panel.innerHTML=optionsPanel();}
 function collection(){refreshPanel();game?.pause(true);const f=current;
  if(f.id==='garden'){showModal('我的小花园',`<p>待种种子 <b>${store.seeds}</b> 颗。空格种花；已有花点开可换位置，不会因为没来而枯萎。</p><label>这次种什么</label><div class="option-list">${f.options.map((x,i)=>btn(x,'seed:'+i,'',`aria-pressed="${option===i}"`)).join('')}</div><div class="garden-grid" style="margin-top:20px">${Array.from({length:9},(_,i)=>{const v=store.garden[i];return btn(v===null||v===undefined?'<span>＋ 种在这里</span>':flowerSVG(v),'plant:'+i,'garden-tile '+(v!==null&&v!==undefined?'planted':''),`aria-label="花圃 ${i+1} ${v===null||v===undefined?'空地':f.options[v]}"`);}).join('')}</div><div class="dialog-actions">${btn('再打一洞得种子','garden-next','primary')}</div>`);return;}
  if(f.id==='travel'){showModal('小球的旅行相册',store.postcards.length?`<div class="stack">${store.postcards.map((card,i)=>`<div class="postcard"><strong>${card.place} · 第 ${card.station} 站</strong><p>${esc(card.note)} · ${card.strokes} 杆</p>${btn('打开明信片','card:'+i,'quiet')}</div>`).join('')}</div><div class="dialog-actions">${btn('继续旅行','travel-next','primary')}</div>`:'<p>还没有明信片。打一洞，带一条自己的球路回来。</p><div class="dialog-actions">'+btn('回到草坪','close-modal','primary')+'</div>');return;}
  if(f.id==='mouth'){showModal('嘴硬语录册',`<p>台词由真实事件收录，未遇到的不会提前算解锁。</p><div class="stack" style="margin-top:18px">${Object.entries(phrases).map(([key,lines])=>`<div class="note-callout"><b>${{shot:'出发',collision:'碰墙',near:'擦洞',water:'入水',stop:'停球',win:'入洞'}[key]}</b><p>${store.quotes.includes(key)?lines[option===1?1:0]:'还没遇到，去球场发现这一句。'}</p></div>`).join('')}</div>`);return;}
  if(f.id==='food'){showModal('九枚点心印章',`<p>完整收集地图点心后进洞，才获得该球友的印章。</p><div class="collection" style="margin-top:18px">${Array.from({length:9},(_,i)=>{const s=Math.floor(i/3),l=i%3;return `<article class="${store.food.includes(`${s}-${l}`)?'':'locked'}"><strong>${f.options[s]}</strong><p>地图 ${l+1} · ${store.food.includes(`${s}-${l}`)?'已收集 ✓':'待发现'}</p></article>`;}).join('')}</div>`);return;}
  if(f.id==='office'){showModal('下班打卡记录',store.stamps.length?store.stamps.map(x=>`<span class="stamp">${x}</span>`).join(''):'<p>还没打过卡。去打一洞，把自己送下班。</p>');return;}
  if(f.id==='sleep'){showModal('今晚的星空',`<p>星星不会熄灭，随时回来接着打。</p><div class="constellation" style="margin-top:20px">${Array.from({length:9},(_,i)=>btn((store.sleep[i]?'★':'☆')+' '+(i+1),'sleep-level:'+i,store.sleep[i]?'done':'')).join('')}</div><div class="dialog-actions">${btn('今天到这里，晚安','home','primary')}</div>`);return;}
  if(f.id==='duel'){showModal('三洞友谊赛记分板',scoreboard()+'<p style="margin-top:15px">每个人完成同样三洞后揭晓结果。未完成的洞不计入总成绩。</p>');return;}
  if(f.id==='daily'){showModal('这几天的个人成绩',`<p>同一天地图固定，旧挑战一直开放。</p><div class="stack">${Array.from({length:7},(_,i)=>`<div class="tiny-record"><span>${dateAt(i)}</span><b>${store.daily[dateAt(i)]?store.daily[dateAt(i)]+' 杆':'未挑战'}</b>${btn('挑战','daily-date:'+i,'quiet')}</div>`).join('')}</div>`);return;}
  if(f.id==='ghost'){showModal('只和自己的最好比',Object.keys(store.ghost).length?Object.values(store.ghost).map(r=>`<div class="tiny-record"><strong>${esc(r.name)}</strong><span>${r.strokes} 杆 · ${r.trace.length} 个采样</span></div>`).join(''):'<p>完成一局后自动保存你的轨迹。这里没有冒充玩家的预录幽灵。</p>');return;}
  if(f.id==='relay'){showModal('这一轮走到哪里了',`<p>${round.scores.map((s,i)=>`第 ${i+1} 洞：${s} 杆`).join('<br>')||'第一洞还在等你。'}</p><div class="line"></div><p>整轮最佳：${store.relay??'尚未完成'}${store.relay?' 杆':''}</p>`);return;}
  if(f.id==='editor'){mapSlots();return;}
  showModal('反弹解题手册',`<p>已获得精通徽章 ${Object.keys(store.mastery).length}/6 枚。</p><div class="stack"><p><b>看路线，不只看球洞。</b><br>第一关先理解距离；第四关借上方空间绕墙，第六关穿过中间窄门。</p><p><b>贴着墙打，会损失一些速度。</b><br>沙地会明显减速，水池会回到本杆起点。</p><p><b>精通徽章</b><br>真实碰撞至少一次且标准杆内入洞。先通关，再追求漂亮的一杆。</p></div>`);
 }
 function postcardMarkup(card){return `<div class="postcard">${postcardSVG(card)}<p>${esc(card.note)}</p><small>${card.place} · 第 ${card.station} 站 · ${card.strokes} 杆</small></div>`;}
 function postcardSVG(card){const m=card.map,t=FP.themes[m.theme]||FP.themes.garden,path=card.trace.map((p,i)=>`${i===0||p.move?'M':'L'}${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 500"><rect width="760" height="500" rx="25" fill="${t[1]}"/>${m.walls.map(r=>`<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" rx="5" fill="${t[2]}"/>`).join('')}${m.sand.map(r=>`<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" rx="12" fill="#e4c58b"/>`).join('')}${m.water.map(r=>`<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" rx="12" fill="#8ebbc1"/>`).join('')}<path d="${path}" stroke="#fff8df" stroke-width="4" fill="none" stroke-linejoin="round"/><circle cx="${m.ball.x}" cy="${m.ball.y}" r="12" fill="#fff8df" stroke="#37553d" stroke-width="2"/><circle cx="${m.hole.x}" cy="${m.hole.y}" r="18" fill="#294d3e"/><path d="M${m.hole.x} ${m.hole.y}v-65l35 10-35 12" fill="${t[3]}" stroke="#35513f" stroke-width="3"/></svg>`;}
 let editingCard=null;
 function cardEditor(card){editingCard=card;showModal('给这条球路留句话',`${postcardMarkup(card)}<label for="card-note">旅行寄语</label><input id="card-note" maxlength="80" value="${esc(card.note)}"><div class="dialog-actions">${btn('保存为 SVG 图片','download-card','primary')}${btn('收好，去下一站','travel-next','')}</div>`);}
 function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('已生成下载文件。');}
 function saveCard(){if(!editingCard)return;editingCard.note=$('card-note')?.value||editingCard.note;save();}
 function exportCard(){saveCard();const card=editingCard;const raw=postcardSVG(card).replace('viewBox="0 0 760 500"','viewBox="0 0 800 710" width="800" height="710"').replace('<rect width="760"','<rect width="800" height="710" fill="#fff8e7"/><g transform="translate(20 20)"><rect width="760"').replace('</svg>',`</g><text x="30" y="550" font-family="sans-serif" font-size="18" fill="#284334">${Array.from({length:Math.ceil([...card.note].length/36)},(_,i)=>`<tspan x="30" dy="24">${esc([...card.note].slice(i*36,(i+1)*36).join(''))}</tspan>`).join('')}</text><text x="30" y="675" font-family="sans-serif" font-size="16" fill="#53654c">${esc(card.place)} / 第 ${card.station} 站 / ${card.strokes} 杆 · FoldPutt</text></svg>`);download(`FoldPutt-${card.id}.svg`,raw,'image/svg+xml');}
 function mapStatus(){const errors=FP.validateMap(draft);return errors.length?'需要调整：'+errors.join(' '):verifiedDraft?'已亲自打通 · 可以保存通关地图':'几何校验通过 · 还需要亲自试玩，验证可解。';}
 function editorPanel(){return `<section class="panel"><h3>${editing?'造一张小草坪':'正在试玩自己的地图'}</h3>${editing?`<div class="editor-tools">${[['ball','起始球'],['hole','球洞'],['wall','横墙'],['vertical','竖墙'],['sand','沙地'],['water','水池'],['star','点心'],['erase','橡皮擦']].map(([id,label])=>btn(label,'tool:'+id,tool===id?'active':'',`aria-pressed="${tool===id}"`)).join('')}</div><div class="row" style="margin-top:12px">${btn('撤销','undo','','id="undo"')}${btn('重做','redo','','id="redo"')}</div><div class="line"></div>${btn('校验并试玩 '+icon('play'),'test-map','primary')}<div class="row" style="margin-top:8px">${btn('精确放置','place-form','quiet')}${btn('选择模板','templates','quiet')}</div>`:`<p>使用同一个拉杆，检验你设计的路线。完成后标记为已通关。</p><div class="dialog-actions">${btn('回编辑器','back-editor','primary')}</div>`}</section><section class="panel"><h3>把自己的球场收好</h3><p>3 个本地槽位；可保存草稿，已通关与未验证会明确标记。</p><div class="dialog-actions">${btn('存档 / 读取','map-slots','')}${btn('导出地图','export-map','')}</div><label>读取地图文件<input type="file" id="import-map" accept=".json,application/json"></label></section><section class="panel"><h3>给造图的人一个小建议</h3><p>先放球和洞，再增加一面墙。让玩家有选择球路的空间，而不是必须碰运气。</p></section>`;}
 function checkpoint(){history.push(FP.copy(draft));if(history.length>50)history.shift();future=[];editorDirty=true;verifiedDraft=false;}
 function editAt(point){if(!editing)return;const x=Math.round(point.x/30)*30,y=Math.round(point.y/30)*30;place(tool,x,y);}
 function place(kind,x,y){const P=FP.physics;if(x<P.left+15||x>P.right-15||y<P.top+15||y>P.bottom-15){toast('请放在草坪边界内。');return;}checkpoint();if(kind==='ball'||kind==='hole')draft[kind]={x,y};else if(kind==='star'){if(!draft.stars)draft.stars=[];if(draft.stars.length<15)draft.stars.push({x,y});}else if(kind==='erase'){for(const key of ['walls','sand','water'])draft[key]=draft[key].filter(r=>!(x>=r.x-5&&x<=r.x+r.w+5&&y>=r.y-5&&y<=r.y+r.h+5));draft.stars=draft.stars.filter(p=>Math.hypot(p.x-x,p.y-y)>25);}else{const key=kind==='wall'||kind==='vertical'?'walls':kind,ww=kind==='wall'?120:kind==='vertical'?24:90,hh=kind==='wall'?24:kind==='vertical'?120:60;if(draft[key].length<20)draft[key].push({x:Math.max(P.left,Math.min(P.right-ww,x-ww/2)),y:Math.max(P.top,Math.min(P.bottom-hh,y-hh/2)),w:ww,h:hh});}updateEditor();}
 function updateEditor(){if(!game||current?.id!=='editor')return;if(editing){game.world=new FP.World({...FP.copy(draft),theme:'editor'});game.render();const status=$('editor-status');if(status){status.textContent=mapStatus();status.classList.toggle('invalid',FP.validateMap(draft).length>0);}if($('undo'))$('undo').disabled=!history.length;if($('redo'))$('redo').disabled=!future.length;document.querySelectorAll('[data-action^="tool:"]').forEach(b=>{const active=b.dataset.action==='tool:'+tool;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});}}
 function mapSlots(){showModal('三张自己的小草坪',`<label for="map-name">地图名称</label><input id="map-name" value="${esc(draft.name)}" maxlength="30"><div class="stack" style="margin-top:18px">${Array.from({length:3},(_,i)=>{const slot=store.maps[i];return `<div class="note-callout"><b>槽位 ${i+1} · ${slot?esc(slot.map.name):'空'}</b><p>${slot?(slot.verified?'已亲自通关':'草稿 · 可解性未验证'):'保存后可以再读取修改。'}</p><div class="row" style="margin-top:9px">${btn(slot?'覆盖保存':'保存','save-map:'+i,'')}${slot?btn('读取','load-map:'+i,'quiet'):''}</div></div>`;}).join('')}</div>`);}
 function normalizeImport(data){const m=data.map||data;if(!m||!Array.isArray(m.walls)||!Array.isArray(m.sand)||!Array.isArray(m.water)||!m.ball||!m.hole)throw Error('不是有效的地图文件。');const result={name:String(m.name||'导入的小地图').slice(0,30),ball:{x:Number(m.ball.x),y:Number(m.ball.y)},hole:{x:Number(m.hole.x),y:Number(m.hole.y)},walls:m.walls.map(r=>({x:Number(r.x),y:Number(r.y),w:Number(r.w),h:Number(r.h)})),sand:m.sand.map(r=>({x:Number(r.x),y:Number(r.y),w:Number(r.w),h:Number(r.h)})),water:m.water.map(r=>({x:Number(r.x),y:Number(r.y),w:Number(r.w),h:Number(r.h)})),stars:(Array.isArray(m.stars)?m.stars:[]).slice(0,15).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=60&&p.x<=700&&p.y>=60&&p.y<=440).map(p=>({x:p.x,y:p.y})),par:Math.max(1,Math.min(12,Number(m.par)||4)),theme:'editor'};const errors=FP.validateMap(result);if(errors.length)throw Error(errors.join(' '));return result;}
 function exportSelection(){const list=FP.features.filter(f=>selected(f.id));if(!list.length){toast('先收藏至少一个玩法。');return;}const text=`# FoldPutt 下一版候选\n\n日期：${dateAt(0)}\n来源：用户本地交互体验后的选择，尚未授权正式实现。\n\n`+list.map(f=>`## ${f.n} ${f.title}\n- 个人评分：${store.ratings[f.id]||'未评分'} / 5\n- 选择理由：${store.notes[f.id]||'未填写'}\n- 定位：${f.recommend}；工作量：${f.cost}\n- 复玩循环：${f.loop.join(' → ')}\n- 市场假设：${f.hook}\n- 风险：${f.risk}\n- 验证指标：${f.measure}\n`).join('\n');download('FoldPutt-我的功能选择.md',text,'text/markdown;charset=utf-8');}
 function tone(kind){if(!store.sound)return;try{if(!ambient)startAudio();const ctx=ambient.ctx,o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=kind==='win'?660:kind==='pickup'?880:260;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.22);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.24);}catch{}}
 function startAudio(){try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),gain=ctx.createGain();gain.gain.value=.007;gain.connect(ctx.destination);const os=[130.81,196].map(hz=>{const o=ctx.createOscillator();o.type='sine';o.frequency.value=hz;o.connect(gain);o.start();return o});ambient={ctx,gain,os};}catch{store.sound=false;toast('此浏览器暂不支持声音，其他功能正常。');}}
 function stopAudio(){ambient?.ctx.close();ambient=null;}
 document.addEventListener('visibilitychange',()=>{if(document.hidden){game?.pause(true);ambient?.ctx.suspend();}else{if(!$('modal').open)game?.pause(false);if(store.sound)ambient?.ctx.resume();}});
 media.addEventListener('change',()=>{document.body.classList.toggle('reduced',reduced());if(game){game.reduced=reduced();game.render();}if($('modal').open&&$('modal-title').textContent==='按你的节奏来')settings();});
 document.addEventListener('input',e=>{if(e.target.dataset.note){store.notes[e.target.dataset.note]=e.target.value;save();}});
 document.addEventListener('change',async e=>{if(e.target.id==='import-map'){const file=e.target.files[0];if(!file)return;try{if(file.size>60000)throw Error('地图文件不能超过 60KB。');const m=normalizeImport(JSON.parse(await file.text()));checkpoint();draft=m;verifiedDraft=false;renderPlay();toast('已导入地图，请亲自试玩验证。');}catch(err){toast(err.message);}}});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const [action,a,z]=b.dataset.action.split(':');switch(action){
  case'home':goHome();home();break;
  case'filter':filter=a;home();break;
  case'open':openFeature(a);break;
  case'pick':togglePick(a);break;
  case'compare':compare();break;
  case'shelf':shelf();break;
  case'shelf-open':openFeature(a);collection();break;
  case'guide':guide();break;
  case'settings':settings();break;
  case'close-modal':closeModal();break;
  case'result':resultModal();break;
  case'resume':closeModal();break;
  case'pause':showModal('让小球歇一会儿。',`<p>这一杆和进度已经暂停。回来时继续，不会重开。</p><div class="dialog-actions">${btn('继续这局','resume','primary')}${btn('重新开始当局','restart','')}</div>`);break;
  case'motion':store.reduced=!store.reduced;save();if(game)game.reduced=reduced();document.body.classList.toggle('reduced',reduced());settings();break;
  case'sound':store.sound=!store.sound;if(store.sound){startAudio();tone('pickup');}else stopAudio();save();settings();break;
  case'classic':store.classic=!store.classic;save();if(game){game.settings.classic=store.classic;game.render();}settings();break;
  case'option':if(current.id==='mouth'){option=Number(a);if(game)game.skin=option;const w=game?.world; // These choices only change presentation; preserve the shot.
    document.querySelectorAll('[data-action^="option:"]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.action==='option:'+a));game?.render();toast(current.options[option]+' 已选择，当前球路保留。');
   }else{option=Number(a);level=0;if(current.id==='duel'||current.id==='relay'){round.duel=[[],[]];round.scores=[];round.player=0;}renderPlay();}break;
  case'level':level=Number(a);renderPlay();break;
  case'restart':if(game?.world.phase==='won')retryResult();else{closeModal();renderPlay();}break;
  case'collection':collection();break;
  case'insight':insight();break;
  case'next-result':nextResult();break;
  case'retry-result':retryResult();break;
  case'seed':option=Number(a);collection();break;
  case'plant':{const i=Number(a);if(store.garden[i]!=null){showModal('挪一挪这朵小花',`<p>移栽会把这朵花收回为一颗种子，可以重新选择空地。</p><div class="dialog-actions">${btn('收回种子','uproot:'+i,'primary')}${btn('留在这里','collection','')}</div>`);}else if(store.seeds>0){store.garden[i]=option;store.seeds--;save();collection();toast('种下了一朵'+current.options[option]+'。');}else toast('先完成一洞，带一颗种子回来。');break;}
  case'uproot':if(store.garden[Number(a)]!=null){store.garden[Number(a)]=null;store.seeds++;save();}collection();break;
  case'garden-next':closeModal();level=(level+1)%3;renderPlay();break;
  case'sleep-level':closeModal();level=Number(a);renderPlay();break;
  case'travel-next':saveCard();editingCard=null;closeModal();level++;if(level===3){level=0;option=(option+1)%3;}renderPlay();break;
  case'card':cardEditor(store.postcards[Number(a)]);break;
  case'download-card':exportCard();break;
  case'daily-date':option=Number(a);closeModal();renderPlay();break;
  case'names':showModal('谁来一起打一局？',`<label for="name-a">A 球友</label><input id="name-a" maxlength="12" value="${esc(round.names[0])}"><label for="name-b">B 球友</label><input id="name-b" maxlength="12" value="${esc(round.names[1])}"><div class="dialog-actions">${btn('就用这两个名字','save-names','primary')}</div>`);break;
  case'save-names':round.names=[$('name-a').value.trim()||'小草',$('name-b').value.trim()||'小风'];closeModal();if(game?.world.strokes)toast('昵称已更新，当前这一局保留。');else renderPlay();break;
  case'rate':store.ratings[a]=Number(z);save();compare();break;
  case'export-selection':exportSelection();break;
  case'tool':tool=a;updateEditor();break;
  case'undo':if(history.length){future.push(FP.copy(draft));draft=history.pop();verifiedDraft=false;updateEditor();}break;
  case'redo':if(future.length){history.push(FP.copy(draft));draft=future.pop();verifiedDraft=false;updateEditor();}break;
  case'test-map':{const errors=FP.validateMap(draft);if(errors.length){toast(errors[0]);return;}editing=false;renderPlay();break;}
  case'back-editor':closeModal();editing=true;renderPlay();break;
  case'templates':showModal('从哪张草坪开始？',`<p>会替换当前草稿，可用撤销找回。</p><div class="dialog-actions">${['空白草坪','回廊模板','小岛模板'].map((t,i)=>btn(t,'template:'+i,'')).join('')}</div>`);break;
  case'template':checkpoint();draft={...FP.copy(FP.maps[Number(a)]),name:['我的小草坪','回廊小试','小岛散步'][Number(a)],theme:'editor'};if(a==='0'){draft.walls=[];draft.sand=[];draft.water=[];draft.stars=[];}closeModal();renderPlay();break;
  case'map-slots':mapSlots();break;
  case'save-map':draft.name=$('map-name').value.trim()||'我的小草坪';store.maps[Number(a)]={map:FP.copy(draft),verified:verifiedDraft};save();mapSlots();toast('地图已保存到槽位 '+(Number(a)+1));break;
  case'load-map':if(store.maps[Number(a)]){checkpoint();draft=FP.copy(store.maps[Number(a)].map);verifiedDraft=!!store.maps[Number(a)].verified;closeModal();editing=true;renderPlay();}break;
  case'export-map':download('FoldPutt-我的地图.json',JSON.stringify({format:'FoldPutt.PlayClub.Map.v1',map:draft,verified:verifiedDraft},null,2),'application/json');break;
  case'place-form':showModal('键盘精确放置',`<p>当前工具：${tool}。X 为 65–695，Y 为 65–435，使用同一网格坐标。</p><label for="place-x">X 坐标</label><input id="place-x" type="number" min="65" max="695" value="380"><label for="place-y">Y 坐标</label><input id="place-y" type="number" min="65" max="435" value="250"><div class="dialog-actions">${btn('放在这里','place-confirm','primary')}</div>`);break;
  case'place-confirm':{const x=Number($('place-x').value),y=Number($('place-y').value);if(!Number.isFinite(x)||!Number.isFinite(y)){toast('请输入有效坐标。');return;}place(tool,x,y);closeModal();break;}
 }});
 window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(route==='compare')compare();else if(route==='shelf')shelf();else if(route.startsWith('play/'))openFeature(route.split('/')[1]);else home();});
 // Read-only diagnostic snapshot for reproducible prototype verification; no win/score injection.
 FP.inspect=()=>({view,feature:current?.id,option,level,round:FP.copy(round),editing,draft:FP.copy(draft),phase:game?.world.phase,ball:game?FP.copy(game.world.ball):null,strokes:game?.world.strokes,map:game?FP.copy(game.world.map):null,paused:game?.paused,reduced:reduced(),progress:FP.copy(store)});
 const initial=location.hash.slice(1);if(initial.startsWith('play/'))openFeature(initial.split('/')[1]);else if(initial==='compare')compare();else if(initial==='shelf')shelf();else home();
})();
